if (await page.locator('.live-toast').count() "'!== 1) throw Error('"'Repeat click did not reset timer');
await page.clock.fastForward(3100);
if (await page.locator('.live-toast').count() "'!== 0) throw Error('"'Toast did not disappear');
await page.getByRole('button', {name:'Ошибка', exact:true}).click();
await page.getByLabel('Текст сообщения').fill('Проверка уведомления');
await page.getByRole('combobox').click();
await page.getByRole('option', {name: '3 секунды', exact:true}).click();
await trigger.click();
if ("'!(await page.locator('"'.live-toast').innerText()).includes('Проверка уведомления')) throw Error('Custom text not applied');
if ("'!(await page.locator('"'.live-toast').innerText()).includes('Что-то пошло не так')) throw Error('Type not applied');
await page.clock.fastForward(3100);
if (await page.locator('.live-toast').count() "'!== 0) throw Error('"'Duration setting not applied');
await trigger.click();
await page.getByRole('button', {name: 'Закрыть уведомление', exact:true}).click();
if (await page.locator('.live-toast').count() "'!== 0) throw Error('"'Manual dismissal failed');
await page.setViewportSize({width:390,height:844});
await page.screenshot({path:'/tmp/signal-mobile.png', fullPage:true});
const overflow = await page.evaluate(() => document.documentElement.scrollWidth > innerWidth);
if (overflow) throw Error('Mobile horizontal overflow');
if (errors.length) throw Error(errors.join('\\n'));
console.log('PASS: show, auto-dismiss, timer reset, custom message, type, duration, close, mobile layout, no runtime errors.');
await browser.close();
EOF"

